const $=s=>document.querySelector(s);
function make(tag,cls,text){const e=document.createElement(tag);if(cls)e.className=cls;if(text!=null)e.textContent=text;return e}
function ensureDimensionHud(){let hud=$('#ggDimensionHud');if(hud)return hud;hud=make('section','gg-tech-hud gg-dimension-hud');hud.id='ggDimensionHud';hud.hidden=true;const head=make('div','gg-hud-head');head.append(make('strong','', 'COTAS DO ELEMENTO'));const close=make('button','gg-hud-close','×');close.type='button';close.title='Ocultar cotas';close.onclick=()=>$('#hideDimensions')?.click();head.append(close);const values=make('div','gg-hud-values');values.id='ggDimensionHudValues';const views=make('div','gg-hud-actions');[['3D','iso'],['Vista A','0'],['Vista B','1'],['Vista C','2']].forEach(([label,v])=>{const b=make('button','',label);b.type='button';b.onclick=()=>document.querySelector(`[data-dimension-view="${v}"]`)?.click();views.append(b)});hud.append(head,values,views);document.body.append(hud);return hud}
function syncDimensionHud(){const hud=ensureDimensionHud(),active=document.body.classList.contains('dimensions-active')&&!$('#dimensionPanel')?.hidden;hud.hidden=!active;if(!active)return;const dst=$('#ggDimensionHudValues');dst.replaceChildren();for(const s of document.querySelectorAll('#dimensionValues span'))dst.append(make('span','gg-hud-chip',s.textContent.trim()))}
function ensureSectionHud(){let hud=$('#ggSectionHud');if(hud)return hud;hud=make('section','gg-tech-hud gg-section-hud');hud.id='ggSectionHud';hud.hidden=true;const head=make('div','gg-hud-head');head.append(make('strong','','CORTE AMPLIADO'));const context=make('div','gg-hud-context','');context.id='ggSectionContext';head.append(context);hud.append(head);const values=make('div','gg-hud-values');values.id='ggSectionHudValues';hud.append(values);const row=make('div','gg-section-range'),range=make('input');range.type='range';range.min='0';range.max='100';range.step='1';range.id='ggSectionRange';range.setAttribute('aria-label','Posição do corte');const pos=make('output','gg-section-pos','50%');pos.id='ggSectionPos';row.append(range,pos);hud.append(row);const actions=make('div','gg-hud-actions gg-section-actions'),axis=make('select','gg-axis-select');axis.id='ggSectionAxis';axis.setAttribute('aria-label','Eixo do corte');[['auto','Eixo auto'],['x','X'],['y','Y'],['z','Z']].forEach(([v,t])=>axis.add(new Option(t,v)));actions.append(axis);const closeup=make('button','','Corte');closeup.type='button';closeup.onclick=()=>window.GG_VIEWER_API?.frameSection?.();actions.append(closeup);const whole=make('button','','Peça inteira');whole.type='button';whole.onclick=()=>window.GG_VIEWER_API?.fit?.();actions.append(whole);const back=make('button','gg-primary-small','Voltar');back.type='button';back.onclick=()=>$('#closeSection')?.click();actions.append(back);hud.append(actions);range.oninput=()=>{const src=$('#sectionPosition');if(!src)return;src.value=range.value;src.dispatchEvent(new Event('input',{bubbles:true}));syncSectionHud()};range.onchange=()=>{const src=$('#sectionPosition');if(!src)return;src.value=range.value;src.dispatchEvent(new Event('change',{bubbles:true}))};axis.onchange=()=>{const src=$('#sectionAxis');if(!src)return;src.value=axis.value;src.dispatchEvent(new Event('change',{bubbles:true}));setTimeout(syncSectionHud,0)};document.body.append(hud);return hud}
function syncSectionHud(){const hud=ensureSectionHud(),info=window.GG_SECTION_INFO,active=document.body.classList.contains('section-active')&&!!info;hud.hidden=!active;if(!active)return;const values=$('#ggSectionHudValues');values.replaceChildren();const chips=[`B: ${info.width||'—'}`,`H: ${info.height||'—'}`,`Peça: ${info.pieceLength||'—'}`];for(const b of info.bars||[])chips.push(b);chips.forEach(t=>values.append(make('span','gg-hud-chip',t)));const src=$('#sectionPosition'),range=$('#ggSectionRange'),pos=$('#ggSectionPos');if(src&&range)range.value=src.value;if(pos)pos.textContent=info.positionText||`${src?.value||50}%`;const axisSrc=$('#sectionAxis'),axis=$('#ggSectionAxis');if(axisSrc&&axis)axis.value=axisSrc.value;const name=$('#elementName')?.textContent?.trim();$('#ggSectionContext').textContent=name?` · ${name}`:''}
window.addEventListener('gg-section-update',syncSectionHud);new MutationObserver(()=>{syncDimensionHud();syncSectionHud()}).observe(document.body,{attributes:true,attributeFilter:['class'],subtree:false});const dimSource=$('#dimensionValues');if(dimSource)new MutationObserver(syncDimensionHud).observe(dimSource,{subtree:true,childList:true,characterData:true});window.addEventListener('resize',()=>{syncDimensionHud();syncSectionHud()},{passive:true});setInterval(()=>{syncDimensionHud();syncSectionHud()},1000);ensureDimensionHud();ensureSectionHud();syncDimensionHud();syncSectionHud();